export function isSafeObjectKey(key: string) {
  return key.length > 0 && key.length < 400 && !key.includes("..") &&
    !key.startsWith("/") && /^[A-Za-z0-9._/-]+$/.test(key);
}

export function isProjectImageKey(key: string) {
  return isSafeObjectKey(key) && key.startsWith("projects/") && !key.endsWith("/");
}

// Only relative URLs generated by this application refer to its R2 objects.
export function mediaKeyFromUrl(url: string | null | undefined) {
  if (!url?.startsWith("/api/media/")) return null;
  try {
    const key = decodeURIComponent(url.slice("/api/media/".length));
    return isProjectImageKey(key) ? key : null;
  } catch { return null; }
}

export const IMAGE_TYPES: Record<string, string> = {
  "image/jpeg": "jpg", "image/png": "png", "image/webp": "webp",
  "image/gif": "gif", "image/avif": "avif",
};

export function imageBytesMatch(bytes: Uint8Array, type: string) {
  const ascii = (start: number, length: number) => String.fromCharCode(...bytes.slice(start, start + length));
  if (type === "image/jpeg") return bytes[0] === 255 && bytes[1] === 216 && bytes[2] === 255;
  if (type === "image/png") return [137,80,78,71,13,10,26,10].every((b, i) => bytes[i] === b);
  if (type === "image/gif") return ["GIF87a", "GIF89a"].includes(ascii(0, 6));
  if (type === "image/webp") return ascii(0, 4) === "RIFF" && ascii(8, 4) === "WEBP";
  if (type === "image/avif") return ascii(4, 4) === "ftyp" && (ascii(8, 4) === "avif" || ascii(8, 4) === "avis" || ascii(16, 32).match(/avif|avis/) !== null);
  return false;
}
